import numpy as np
one=np.ones_like(t)
lib={}
for i in range(3):
  for j in range(4):
    for k in range(3):
      if i+j+k>0: lib[f't{i}x{j}v{k}']=(t**i)*(x**j)*(v**k)
lib['vabsv']=v*np.abs(v); lib['sin_t']=np.sin(t); lib['cos_t']=np.cos(t); lib['sinx']=np.sin(x); lib['cosx']=np.cos(x)
lib['xabsx']=x*np.abs(x); lib['xabsx_v']=x*np.abs(x)*v
names=list(lib); chosen=[]
def sc(nm):
    A=np.column_stack([one]+[lib[n] for n in nm])
    c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    r=dv_dt-A@c
    return np.mean(r**2)/np.var(dv_dt),c
for step in range(10):
    best=min(((sc(chosen+[n])[0],n) for n in names if n not in chosen))
    chosen.append(best[1])
    print(step,best[1],'%.6g'%best[0])
s,c=sc(chosen); print(dict(zip(['c0']+chosen,c.round(4))))
